content.text:
The degradation comes from one fault: ts-seat-service aborting its outgoing HTTP GET calls to ts-config-service. It is an `http_aborted` fault at the caller, and its failure spreads through travel and route-plan to the user-facing dashboard.

```json
{
  "root_causes": [
    {
      "service": "ts-seat-service",
      "fault_kind": "http_aborted",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name caller, s.service_name callee, count(*) n, sum(CASE WHEN c.attr_status_code='Error' THEN 1 ELSE 0 END) c_errs, sum(CASE WHEN s.attr_status_code='Error' THEN 1 ELSE 0 END) s_errs, quantile_cont(c.duration,0.95)/1e6 c_p95, quantile_cont(s.duration,0.95)/1e6 s_p95 FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id=c.span_id AND s.trace_id=c.trace_id WHERE c.attr_span_kind='Client' AND s.attr_span_kind='Server' AND c.service_name='ts-seat-service' GROUP BY ALL ORDER BY n DESC",
          "claim": "All 3036 seat-to-config client calls error, while config's own server spans show no errors."
        },
        {
          "kind": "log",
          "sql": "SELECT service_name, level, count(*) n FROM abnormal_logs WHERE service_name='ts-seat-service' AND level='SEVERE' AND message LIKE '%ts-config-service%Unexpected end of file%' GROUP BY ALL",
          "claim": "Seat-service SEVERE logs show I/O 'Unexpected end of file' on GET to ts-config-service configs path, 1518 times."
        },
        {
          "kind": "trace",
          "sql": "SELECT span_name, attr_status_code, attr_span_kind, count(*) n FROM abnormal_traces WHERE service_name='ts-seat-service' AND attr_span_kind='Client' GROUP BY ALL ORDER BY n DESC",
          "claim": "Seat's GET client spans to config all error, while its POST client spans to other services stay Unset (normal)."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-seat-service",
      "to": "ts-travel-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name caller, s.service_name callee, count(*) n, sum(CASE WHEN c.attr_status_code='Error' THEN 1 ELSE 0 END) c_errs, quantile_cont(c.duration,0.95)/1e6 c_p95 FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id=c.span_id AND s.trace_id=c.trace_id WHERE c.attr_span_kind='Client' AND s.attr_span_kind='Server' AND c.service_name='ts-travel-service' AND s.service_name='ts-seat-service' GROUP BY ALL",
          "claim": "Travel-service's POST calls to seat-service error on about 632 of 640 calls, with p95 near 12s."
        }
      ]
    },
    {
      "from": "ts-seat-service",
      "to": "ts-travel2-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name caller, s.service_name callee, count(*) n, sum(CASE WHEN c.attr_status_code='Error' THEN 1 ELSE 0 END) c_errs FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id=c.span_id AND s.trace_id=c.trace_id WHERE c.attr_span_kind='Client' AND s.attr_span_kind='Server' AND c.service_name='ts-travel2-service' AND s.service_name='ts-seat-service' GROUP BY ALL",
          "claim": "Travel2-service's calls to seat-service error on all 860 calls, with seat server spans also in error."
        }
      ]
    },
    {
      "from": "ts-travel-service",
      "to": "ts-route-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name caller, s.service_name callee, count(*) n, sum(CASE WHEN c.attr_status_code='Error' THEN 1 ELSE 0 END) c_errs, quantile_cont(c.duration,0.95)/1e6 c_p95 FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id=c.span_id AND s.trace_id=c.trace_id WHERE c.attr_span_kind='Client' AND s.attr_span_kind='Server' AND c.service_name='ts-route-plan-service' AND s.service_name='ts-travel-service' GROUP BY ALL",
          "claim": "Route-plan's calls to travel-service error on 35 of 45 calls, with p95 near 60s."
        }
      ]
    },
    {
      "from": "ts-travel2-service",
      "to": "ts-route-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name caller, s.service_name callee, count(*) n, sum(CASE WHEN c.attr_status_code='Error' THEN 1 ELSE 0 END) c_errs, quantile_cont(c.duration,0.95)/1e6 c_p95 FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id=c.span_id AND s.trace_id=c.trace_id WHERE c.attr_span_kind='Client' AND s.attr_span_kind='Server' AND c.service_name='ts-route-plan-service' AND s.service_name='ts-travel2-service' GROUP BY ALL",
          "claim": "Route-plan's calls to travel2-service error on 56 of 58 calls, with p95 near 60s."
        }
      ]
    },
    {
      "from": "ts-route-plan-service",
      "to": "ts-travel-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name caller, s.service_name callee, count(*) n, sum(CASE WHEN c.attr_status_code='Error' THEN 1 ELSE 0 END) c_errs, quantile_cont(c.duration,0.95)/1e6 c_p95 FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id=c.span_id AND s.trace_id=c.trace_id WHERE c.attr_span_kind='Client' AND s.attr_span_kind='Server' AND c.service_name='ts-travel-plan-service' AND s.service_name='ts-route-plan-service' GROUP BY ALL",
          "claim": "Travel-plan's calls to route-plan error on 9 of 11 calls, with p95 near 60s."
        }
      ]
    },
    {
      "from": "ts-travel-plan-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, count(*) n, quantile_cont(duration,0.95)/1e6 p95_ms FROM abnormal_traces WHERE service_name='ts-ui-dashboard' GROUP BY ALL ORDER BY n DESC LIMIT 5",
          "claim": "Ui-dashboard request p95 rises to about 20s during the incident, matching the timed-out travel-plan chain."
        }
      ]
    }
  ]
}
```

